COCO_FACTS_SQL = "\nSELECT\n    sub_surface,\n    usage_date,\n    user_name,\n    model_name,\n    role_name,\n    inference_region,\n    COUNT(*)     AS calls,\n    SUM(tokens)  AS tokens,\n    SUM(credits) AS credits,\n    SUM(NVL(tg:input::NUMBER, 0)) AS tok_input,\n    SUM(NVL(tg:output::NUMBER, 0)) AS tok_output,\n    SUM(NVL(tg:cache_read_input::NUMBER, 0)) AS tok_cache_read_input,\n    SUM(NVL(tg:cache_write_input::NUMBER, 0)) AS tok_cache_write_input\nFROM (\n    SELECT\n        'CLI'                                               AS sub_surface,\n        CONVERT_TIMEZONE('UTC', USAGE_TIME)::DATE                       AS usage_date,\n        NVL(USER_NAME, '(unknown)')                            AS user_name,\n        NVL(METADATA:role_name::STRING, '(unknown)')           AS role_name,\n        NVL(METADATA:inference_region::STRING, '(unknown)')    AS inference_region,\n        NVL(OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING, '(unknown)') AS model_name,\n        NVL(TOKENS, 0)                                        AS tokens,\n        NVL(TOKEN_CREDITS, 0)                                 AS credits,\n        GET(TOKENS_GRANULAR, OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING) AS tg\n    FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_CODE_CLI_USAGE_HISTORY\n    WHERE USAGE_TIME >= ?::TIMESTAMP_TZ AND USAGE_TIME < ?::TIMESTAMP_TZ\n    UNION ALL\n    SELECT\n        'Desktop'                                               AS sub_surface,\n        CONVERT_TIMEZONE('UTC', USAGE_TIME)::DATE                       AS usage_date,\n        NVL(USER_NAME, '(unknown)')                            AS user_name,\n        NVL(METADATA:role_name::STRING, '(unknown)')           AS role_name,\n        NVL(METADATA:inference_region::STRING, '(unknown)')    AS inference_region,\n        NVL(OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING, '(unknown)') AS model_name,\n        NVL(TOKENS, 0)                                        AS tokens,\n        NVL(TOKEN_CREDITS, 0)                                 AS credits,\n        GET(TOKENS_GRANULAR, OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING) AS tg\n    FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_CODE_DESKTOP_USAGE_HISTORY\n    WHERE USAGE_TIME >= ?::TIMESTAMP_TZ AND USAGE_TIME < ?::TIMESTAMP_TZ\n    UNION ALL\n    SELECT\n        'Snowsight'                                               AS sub_surface,\n        CONVERT_TIMEZONE('UTC', USAGE_TIME)::DATE                       AS usage_date,\n        NVL(USER_NAME, '(unknown)')                            AS user_name,\n        NVL(METADATA:role_name::STRING, '(unknown)')           AS role_name,\n        NVL(METADATA:inference_region::STRING, '(unknown)')    AS inference_region,\n        NVL(OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING, '(unknown)') AS model_name,\n        NVL(TOKENS, 0)                                        AS tokens,\n        NVL(TOKEN_CREDITS, 0)                                 AS credits,\n        GET(TOKENS_GRANULAR, OBJECT_KEYS(TOKENS_GRANULAR)[0]::STRING) AS tg\n    FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_CODE_SNOWSIGHT_USAGE_HISTORY\n    WHERE USAGE_TIME >= ?::TIMESTAMP_TZ AND USAGE_TIME < ?::TIMESTAMP_TZ\n)\nGROUP BY ALL\n"
